// Copyright (c) 2026 Roshan. All rights reserved.// Proprietary license — see LICENSE file for details.package com.roshan.persona.brain.llm.providerimport com.roshan.persona.common.Result/** * NOUS — Local LLM provider interface. * * Wraps llama.cpp via JNI for on-device LLM inference with Vulkan GPU * acceleration. Real implementation lives in :native:llamacpp + :feature:llm * (Module 4). Brain uses this interface to stay testable without llama.cpp. * * Lifecycle: *   1. [load] — load model into memory (slow, ~5-30s depending on model size) *   2. [generate] — generate text with streaming token callback *   3. [embed] — generate embedding for semantic cache (optional) *   4. [unload] — free model from memory * * Thread safety: All methods must be safe to call from any coroutine. * Internally uses [com.roshan.persona.common.LlmDispatcher] (single-threaded) * to serialize inference calls. * * @see <a href="docs/spec/module2-spec-review.pdf">§7 Layer 3</a> */interface LocalLlmProvider {    /** Unique model ID (e.g., "qwen2.5-0.5b-instruct-q4"). */    val modelId: String    /** Whether the model is currently loaded in memory. */    val isLoaded: Boolean    /** Maximum context length in tokens (model-specific). */    val contextLength: Int    /** Available GPU VRAM in MB (0 if no GPU). */    val availableVramMb: Int    /** Model file size in bytes. */    val modelSizeBytes: Long    /**     * Load the model into memory.     *     * @return Success or Failure (model missing, OOM, corrupted file).     */    suspend fun load(): Result<Unit>    /** Unload the model from memory. */    suspend fun unload(): Result<Unit>    /**     * Generate text from a prompt with streaming token callback.     *     * @param prompt the full prompt (system + context + user input)     * @param config generation parameters     * @param onToken called for each generated token (for streaming UI)     * @return [GenerationResult] with full text + metadata     */    suspend fun generate(        prompt: String,        config: GenerationConfig,        onToken: (String) -> Unit,    ): Result<GenerationResult>    /**     * Generate embedding for a text (for semantic cache).     * Returns 384-dim float vector.     *     * Note: Not all LLM models support embeddings. If unsupported, returns Failure.     */    suspend fun embed(text: String): Result<FloatArray>}/** * NOUS — Generation configuration. * * @see <a href="docs/spec/module2-spec-review.pdf">§7.1 GenerationConfig</a> */data class GenerationConfig(    val maxTokens: Int = 512,    val temperature: Float = 0.7f,    val topP: Float = 0.9f,    val topK: Int = 40,    val repeatPenalty: Float = 1.1f,    val seed: Long? = null,  // null = random    val stopSequences: List<String> = emptyList(),    val streamTokens: Boolean = true,) {    init {        require(maxTokens in 1..32_768) { "maxTokens must be 1-32768, was $maxTokens" }        require(temperature in 0.0f..2.0f) { "temperature must be 0.0-2.0, was $temperature" }        require(topP in 0.0f..1.0f) { "topP must be 0.0-1.0, was $topP" }        require(topK in 1..100) { "topK must be 1-100, was $topK" }        require(repeatPenalty in 0.5f..2.0f) { "repeatPenalty must be 0.5-2.0, was $repeatPenalty" }    }    companion object {        /** Fast generation — for short answers. */        val FAST = GenerationConfig(            maxTokens = 128,            temperature = 0.5f,            topP = 0.85f,            topK = 30,        )        /** Balanced — default for most queries. */        val BALANCED = GenerationConfig()        /** Creative — for brainstorming, writing. */        val CREATIVE = GenerationConfig(            maxTokens = 1024,            temperature = 1.1f,            topP = 0.95f,            topK = 50,        )        /** Deterministic — for factual answers (temperature = 0). */        val DETERMINISTIC = GenerationConfig(            maxTokens = 256,            temperature = 0.0f,            topP = 1.0f,            topK = 1,            seed = 42L,        )    }}/** * NOUS — Generation result. */data class GenerationResult(    val text: String,    val tokensGenerated: Int,    val tokensPerSecond: Float,    val durationMs: Long,    val finishReason: FinishReason,    val promptTokens: Int,    val modelId: String,)/** * Why generation stopped. */enum class FinishReason {    /** Natural stop — model generated end-of-text token. */    STOP,    /** Hit maxTokens limit. */    LENGTH,    /** Hit a stop sequence. */    STOP_SEQUENCE,    /** Error during generation. */    ERROR,    /** Out of memory — KV cache full. */    OOM,    /** Input exceeded context length. */    CONTEXT_OVERFLOW,}